1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM = 25;
4	const COMPONENT_TYPES = ["rune", "moonstone"];
5	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: COMPONENT_BASE_PREMIUM,
11	  moonstone: COMPONENT_BASE_PREMIUM,
12	};
13	const COMPONENT_BLOCK_SIZE = 3;
14	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
15	const CURSED_SURCHARGE_RATE = 0.5;
16	
17	type Item = {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	};
23	
24	type Step = {
25	  op: string;
26	  items: Item[];
27	};
28	
29	type Scenario = {
30	  customer: { yearsWithMHPCO: number };
31	  steps: Step[];
32	};
33	
34	type QuoteResult = {
35	  premium: number;
36	};
37	
38	type ScenarioOutput = {
39	  results: QuoteResult[];
40	};
41	
42	const isComponent = (item: Item): boolean =>
43	  COMPONENT_TYPES.includes(item.type);
44	
45	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
46	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
47	  sameTypeItems.every(isComponent);
48	
49	const groupByType = (items: Item[]): Item[][] => {
50	  const groups = new Map<string, Item[]>();
51	  for (const item of items) {
52	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
53	  }
54	  return [...groups.values()];
55	};
56	
57	const basePremiumForItem = (item: Item): number =>
58	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
59	
60	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
61	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
62	  return sameTypeItems.reduce(
63	    (total, item) => total + basePremiumForItem(item),
64	    0,
65	  );
66	};
67	
68	const basePremiumForItems = (items: Item[]): number =>
69	  groupByType(items).reduce(
70	    (total, group) => total + basePremiumForGroup(group),
71	    0,
72	  );
73	
74	const cursedSurcharge = (item: Item): number =>
75	  item.cursed ? basePremiumForItem(item) * CURSED_SURCHARGE_RATE : 0;
76	
77	const totalItemSurcharges = (items: Item[]): number =>
78	  items.reduce((total, item) => total + cursedSurcharge(item), 0);
79	
80	const premiumBeforeProcessingFee = (items: Item[]): number => {
81	  const basePremium = basePremiumForItems(items);
82	  return (
83	    basePremium +
84	    totalItemSurcharges(items) +
85	    basePremium * FIRST_INSURANCE_SURCHARGE_RATE
86	  );
87	};
88	
89	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
90	  results: scenario.steps.map((step) => ({
91	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
92	  })),
93	});
